def prepend_prolog(content: StringList, prolog: str) -> None:
    """Prepend a string to content body as prolog."""
    if prolog:
        pos = 0
        for idx, line in enumerate(content):
            if docinfo_re.match(line):
                # If the next line looks like a section underline, this line
                # is actually a heading (e.g. ":mod:`foo`" followed by "=====")
                # and not docinfo. Stop counting docinfo here to avoid
                # splitting the heading when inserting the prolog.
                if idx + 1 < len(content):
                    next_line = content[idx + 1]
                    if next_line and len(next_line.strip()) >= 1:
                        stripped = next_line.strip()
                        if len(set(stripped)) == 1 and stripped[0] in '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~':
                            # RST section adornment characters; check if it could be underline
                            # for the current line (allow underline longer than title)
                            break
                pos += 1
            else:
                break

        if pos > 0:
            # insert a blank line after docinfo
            content.insert(pos, '', '<generated>', 0)
            pos += 1

        # insert prolog (after docinfo if exists)
        for lineno, line in enumerate(prolog.splitlines()):
            content.insert(pos + lineno, line, '<rst_prolog>', lineno)

        content.insert(pos + lineno + 1, '', '<generated>', 0)
